window.ExerciseVisuals=(()=>{
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function diagram(key,phase){const bird=key==='birdDog';return '<svg viewBox="0 0 400 240" role="img" aria-label="'+(bird?'Bird dog: '+(phase?'extend opposite arm and leg':'hands under shoulders and knees under hips'):'Chin nod: '+(phase?'small yes nod with head supported':'head resting on folded towel'))+'"><path d="M30 205H370" stroke="#789075" stroke-width="3"/><g fill="none" stroke="#d9eac4" stroke-width="10" stroke-linecap="round" stroke-linejoin="round">'+(bird?'<circle cx="123" cy="100" r="20"/><path d="M147 118L265 130M160 122L159 202M258 130L270 172L314 202"/><path stroke="#b6ee92" d="'+(phase?'M156 123L80 132L38 130M260 130L317 129L365 128':'M156 123L127 163L130 202M260 130L244 174L290 202')+'"/>':'<path d="M145 185L270 185L305 150L346 194"/><ellipse cx="105" cy="172" rx="28" ry="23" transform="rotate('+(phase?'7':'0')+' 105 172)"/><path stroke="#b6ee92" d="M83 199H134"/><path stroke-width="3" stroke="#b6ee92" d="M77 138Q62 154 72 171M63 165L72 171L79 163"/>')+'</g><text x="28" y="30" fill="#bdd1b3" font-size="14">'+(bird?(phase?'Reach long. Keep pelvis level.':'Start on all fours.'):(phase?'Small nod. Do not lift the head.':'Rest the head on a folded towel.'))+'</text></svg>';}
function render(key){const m=window.EXERCISE_MEDIA[key];if(!m&&!['birdDog','chinNod'].includes(key))return '';const hold=/neck/.test(key),frames=key==='neckFrontHold'?[0]:key==='neckBackHold'?[1]:[0,1];return '<section class="exercise-visual" data-visual><div class="visual-heading"><strong>See the movement</strong>'+(!hold?'<button type="button" data-play-visual aria-pressed="false">Play positions ▷</button>':'<span>Gentle static holds</span>')+'</div><div class="position-pair">'+frames.map(i=>'<figure data-position="'+i+'">'+(m?'<img src="'+m.images[i]+'" alt="'+esc(m.name)+' — reference position '+(i+1)+'" loading="lazy">':diagram(key,i))+'<figcaption>Position '+(i+1)+'</figcaption></figure>').join('')+'</div><p class="visual-caption">'+(m?'Photographed variation: <strong>'+esc(m.name)+'</strong>. Follow the written steps for your variation.':'Simplified position guide. Follow the steps below for setup and control.')+(hold?' Keep your head still while applying gentle hand pressure.':' Position reference, not a video.')+'</p>'+(m?'<a class="visual-credit" href="https://github.com/yuhonas/free-exercise-db" target="_blank" rel="noopener">Position images · Free Exercise DB (public domain) ↗</a>':'')+'</section>';}
function routineSteps(key){const aliases={dbSquat:'squat',dbSplitSquat:'splitSquat',dbRdl:'rdl',dbPress:'shoulderPress',dbCurl:'cableCurl',machineCurl:'legCurl',calfRaise:'standingCalf',machineCalf:'seatedCalf',dbBentRow:'row',dbRow:'row',machineRow:'row',seatedRow:'row',machineShoulder:'shoulderPress',cableRaise:'lateralRaise',chestPress:'flatPress',cablePress:'flatPress',dbFloorPress:'flatPress',dbNeutralPress:'flatPress'};const specific={dbPress:['Stand with a stable stance, dumbbells at shoulder height and ribs stacked over your pelvis.','Press overhead without leaning back or flaring the ribs.','Lower slowly. Use a standing position for this variation.'],machineShoulder:['Adjust the seat so the machine handles begin around shoulder height.','Keep your back supported and press overhead through a comfortable range.','Return slowly without arching your back.'],cableRaise:['Stand beside a low cable and hold the handle in the outside hand.','Raise your arm slightly forward of your side toward shoulder height.','Lower slowly, keeping your trunk steady.'],bodySquat:['Stand with feet in a comfortable stance and reach your arms forward for balance.','Bend hips and knees together, keeping your whole foot grounded.','Stand smoothly; choose a depth you can control.'],reverseLunge:['Stand beside a stable support. Step one foot back.','Bend both knees and keep the front foot grounded.','Push through the front leg to return, then alternate sides. Use bodyweight for this version.'],wallPushup:['Place hands on a wall at chest height and step back a comfortable distance.','Keep your trunk straight as you bend elbows and bring your chest toward the wall.','Press away slowly. The photograph shows an incline variation; your hands stay on the wall.'],floorPushup:['Place hands slightly wider than your shoulders, with knees or toes supporting you.','Keep a straight line from head to knees or heels. Lower your chest with elbows angled back.','Press up without letting your lower back sag.'],bridge:['Lie on your back, knees bent and feet flat.','Brace gently and lift your hips until thighs and trunk align.','Lower slowly without arching the lower back.'],bridgeHold:['Lie on your back, knees bent and feet flat.','Lift the hips until thighs and trunk align, then pause briefly.','Lower with control; keep ribs down and breathe.'],dbBridge:['Lie on your back with bent knees. Secure a padded dumbbell over your hips.','Lift your hips, keeping the weight steady with your hands.','Lower slowly. Use a dumbbell for this version, even though the reference shows a barbell.'],machineSquat:['Set the seat so your back and pelvis remain supported. Place feet comfortably on the platform.','Lower the platform through a range you can control without your pelvis lifting.','Press through the whole foot; avoid snapping the knees straight.'],hipThrust:['Adjust and secure the padded hip-thrust machine according to its instructions.','Keep feet planted and ribs down as you extend the hips.','Return under control. The photo illustrates hip extension with a barbell; use your machine setup.']};if(specific[key])return specific[key];const e=EXERCISES[aliases[key]||key];if(!e)return ['Set up the equipment for your selected variation.','Move with control through a comfortable range, following the reference positions.','Use the prescribed sets and repetitions and stop if the movement hurts.'];let steps=[...e.steps];if(['dbFloorPress','dbNeutralPress'].includes(key))steps=['Lie on the floor with knees bent and dumbbells over your chest.','Lower until your upper arms gently touch the floor; keep wrists stacked over elbows.','Press smoothly. Keep palms facing one another for the neutral-grip variation.'];if(key==='dbCurl')steps=['Stand tall holding dumbbells with palms forward.','Keep elbows near your sides and curl without swinging.','Lower slowly and keep wrists straight.'];if(['dbRow','dbBentRow'].includes(key))steps=['Hinge at the hips with a controlled spine; support your forearm on your thigh for the one-arm version.','Pull the weight toward your hip without twisting or shrugging.','Lower under control. Use the support described in your routine, even if the photo shows a bench.'];if(['seatedRow','machineRow'].includes(key))steps=['Adjust the cable station or machine and take a comfortable grip.','Pull elbows back while keeping your trunk steady.','Let your arms reach forward under control.'];if(['chestPress','cablePress'].includes(key))steps=['Set handles around chest height with a stable body position.','Press forward, keeping wrists aligned with forearms and shoulders comfortable.','Return slowly without letting the shoulders roll forward.'];return steps;}
let timer=null;function stop(){clearInterval(timer);timer=null;document.querySelectorAll('[data-visual]').forEach(v=>{v.classList.remove('playing');v.dataset.frame='0';const b=v.querySelector('[data-play-visual]');if(b){b.textContent='Play positions ▷';b.setAttribute('aria-pressed','false');}});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-play-visual]');if(b){const v=b.closest('[data-visual]'),playing=v.classList.contains('playing');stop();if(!playing){v.classList.add('playing');v.dataset.frame='0';b.textContent='Pause positions Ⅱ';b.setAttribute('aria-pressed','true');timer=setInterval(()=>v.dataset.frame=v.dataset.frame==='0'?'1':'0',1800);}}const demo=e.target.closest('[data-demo]');if(demo){stop();const key=demo.dataset.demo;info(demo.dataset.name,render(key)+'<h3>How to do your variation</h3><ol>'+routineSteps(key).map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol><p>Use the sets, repetitions and rest periods in your routine. Begin with a comfortable load and controlled movement.</p>');}});
document.addEventListener('close',stop,true);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});return {render};})();
